217	function _easeInOut(t: number): number {
218	  return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
219	}
220	
221	function _clamp01(v: number): number {
222	  return v < 0 ? 0 : v > 1 ? 1 : v;
223	}
224	
225	function _rangeAlpha(p: number, inStart: number, inEnd: number, outStart: number, outEnd: number): number {
226	  if (p < inStart) return 0;
227	  if (p < inEnd) return _easeInOut(_clamp01((p - inStart) / (inEnd - inStart)));
228	  if (p < outStart) return 1;
229	  if (p < outEnd) return _easeInOut(_clamp01(1 - (p - outStart) / (outEnd - outStart)));
230	  return 0;
231	}
