233	function syncProofHeadlines(progress: number): void {
234	  const h1 = getProofH1();
235	  const h2 = getProofH2();
236	  if (!h1 || !h2) return;
237	
238	  const a1 = _rangeAlpha(progress, 0, 0.15, 0.45, 0.6);
239	  const a2 = _rangeAlpha(progress, 0.45, 0.6, 1.1, 1.1);
240	
241	  h1.style.opacity = String(a1);
242	  h1.style.filter = `blur(${(1 - a1) * PROOF_BLUR_PX}px)`;
243	  h2.style.opacity = String(a2);
244	  h2.style.filter = `blur(${(1 - a2) * PROOF_BLUR_PX}px)`;
245	}
246	
247	function resetProofHeadlines(): void {
248	  const h1 = getProofH1();
249	  const h2 = getProofH2();
250	  if (h1) { h1.style.opacity = "0"; h1.style.filter = `blur(${PROOF_BLUR_PX}px)`; }
251	  if (h2) { h2.style.opacity = "0"; h2.style.filter = `blur(${PROOF_BLUR_PX}px)`; }
252	  _proofH1El = null;
253	  _proofH2El = null;
254	}
