264	function syncAboutContactHead(progress: number): void {
265	  const section = document.querySelector<HTMLElement>(ABOUT_CONTACT_SECTION_SELECTOR);
266	  const head = document.querySelector<HTMLElement>(ABOUT_CONTACT_HEAD_SELECTOR);
267	  const actions = document.querySelector<HTMLElement>(ABOUT_CONTACT_ACTIONS_SELECTOR);
268	  if (!section || !head || !actions) return;
269	
270	  const textItems = Array.from(head.querySelectorAll<HTMLElement>(".mask-target"));
271	  const shouldShow = progress >= CONTACT_HEAD_TRANSITION.revealStart;
272	
273	  if (aboutSceneDomState.isContactHeadVisible === shouldShow) return;
274	  aboutSceneDomState.isContactHeadVisible = shouldShow;
275	  aboutSceneDomState.contactHeadTimers = clearTimers(
276	    aboutSceneDomState.contactHeadTimers,
277	  );
278	
279	  if (shouldShow) {
280	    section.dataset.active = "true";
281	    head.dataset.active = "true";
282	    actions.dataset.active = "true";
283	    TextReveal.setVisibleOff(textItems);
284	    textItems.forEach((item, index) => {
285	      const timerId = window.setTimeout(() => {
286	        TextReveal.setVisibleOn(item);
287	      }, index * CONTACT_HEAD_TRANSITION.revealStagger * 1000);
288	      aboutSceneDomState.contactHeadTimers.push(timerId);
289	    });
290	    return;
291	  }
292	
293	  textItems.forEach((item) => {
294	    TextReveal.setVisibleOff(item);
295	  });
296	  section.dataset.active = "false";
297	  head.dataset.active = "false";
298	  actions.dataset.active = "false";
299	}
