303	  const head = document.querySelector<HTMLElement>(ABOUT_CONTACT_HEAD_SELECTOR);
304	  const actions = document.querySelector<HTMLElement>(ABOUT_CONTACT_ACTIONS_SELECTOR);
305	  if (!section || !head || !actions) return;
306	
307	  aboutSceneDomState.isContactHeadVisible = false;
308	  aboutSceneDomState.contactHeadTimers = clearTimers(
309	    aboutSceneDomState.contactHeadTimers,
310	  );
311	  section.dataset.active = "false";
312	  head.dataset.active = "false";
313	  actions.dataset.active = "false";
314	
315	  const textItems = Array.from(head.querySelectorAll<HTMLElement>(".mask-target"));
316	  textItems.forEach((item) => TextReveal.setVisibleOff(item));
317	}
