118	function migrateLegacyAboutTheatreState(
119	  savedState: Record<string, unknown>,
120	): Record<string, unknown> {
121	  const sheetsById = readAboutRecord(savedState.sheetsById);
122	  if (!sheetsById) {
123	    return savedState;
124	  }
