136	      return;
137	    }
138	    didChange = true;
139	  });
140	
141	  if (!didChange) {
142	    return savedState;
143	  }
144	
145	  return {
146	    ...savedState,
147	    sheetsById: nextSheetsById,
148	  };
149	}
